import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, resolve } from "node:path";

export function fingerprint(root, { includeBuild = true } = {}) {
  const git = (...args) =>
    execFileSync("git", ["-C", root, ...args], { encoding: "utf8" }).trim();
  const source = createHash("sha256");
  const files = git("ls-files", "-z")
    .split("\0")
    .filter(Boolean)
    .filter((name) =>
      /^(src\/|public\/|scripts\/|package(?:-lock)?\.json$|vite\.config\.ts$|tsconfig\.json$|playwright.*\.config\.ts$)/.test(
        name,
      ),
    );
  files.push("e2e/forest-road-polish.review.ts");
  const helpers = ["e2e/helpers.ts", "e2e/projection.ts"];
  files.push(...helpers);
  for (const name of [...new Set(files)].sort()) {
    source
      .update(name)
      .update("\0")
      .update(readFileSync(resolve(root, name)))
      .update("\0");
  }
  const build = createHash("sha256");
  function visit(relative) {
    for (const entry of readdirSync(resolve(root, relative), {
      withFileTypes: true,
    }).sort((a, b) => a.name.localeCompare(b.name))) {
      const name = `${relative}/${entry.name}`;
      if (entry.isDirectory()) visit(name);
      else
        build
          .update(name)
          .update("\0")
          .update(readFileSync(resolve(root, name)))
          .update("\0");
    }
  }
  if (includeBuild && !existsSync(resolve(root, "dist/index.html")))
    throw new Error(
      "No production dist/index.html; prepare a review build first",
    );
  if (includeBuild) visit("dist");
  const hashFiles = (base, names) => {
    const hash = createHash("sha256");
    for (const name of [...names].sort())
      hash
        .update(name)
        .update("\0")
        .update(readFileSync(resolve(base, name)))
        .update("\0");
    return hash.digest("hex");
  };
  return {
    revision: git("rev-parse", "HEAD"),
    headTree: git("rev-parse", "HEAD^{tree}"),
    sourceSha256: source.digest("hex"),
    helpersSha256: hashFiles(root, helpers),
    harnessSha256: hashFiles(dirname(import.meta.filename), [
      "playwright.config.ts",
      "prepare-build.mjs",
      "provenance.mjs",
      "PROTOCOL.md",
    ]),
    buildSha256: includeBuild ? build.digest("hex") : null,
    dirty: git("status", "--short"),
  };
}

if (process.argv[1] && resolve(process.argv[1]) === import.meta.filename) {
  process.stdout.write(
    JSON.stringify(
      fingerprint(resolve(process.argv[2] ?? "/workspace/avatarrpg-379")),
    ),
  );
}

