// This script builds only when the integration owner explicitly runs it.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fingerprint } from "./provenance.mjs";

const root = resolve(
  process.env.FNT_REVIEW379_SOURCE ?? "/workspace/avatarrpg-379",
);
const startedAt = new Date().toISOString();
const before = fingerprint(root, { includeBuild: false });
if (before.dirty) throw new Error("Refusing review build from a dirty source tree");
let buildError = null;
try {
  execFileSync("npm", ["run", "build"], { cwd: root, stdio: "inherit" });
} catch (error) {
  buildError = error;
}
const afterSource = fingerprint(root, { includeBuild: false });
const stable = JSON.stringify(before) === JSON.stringify(afterSource);
const after = buildError ? afterSource : fingerprint(root);
writeFileSync(
  new URL("./build-receipt.json", import.meta.url),
  JSON.stringify(
    {
      ...after,
      before,
      afterSource,
      stable,
      exitCode: buildError?.status ?? (buildError ? 1 : 0),
      error: buildError?.message ?? null,
      root,
      startedAt,
      finishedAt: new Date().toISOString(),
      command: "npm run build",
      node: process.version,
    },
    null,
    2,
  ),
);
if (buildError) throw buildError;
if (!stable) throw new Error("Source, helpers or harness changed during review build");

